input.content:
import fs from 'fs';

const txt = fs.readFileSync('data/steam.csv', 'utf8').trim().split(/\r?\n/);
const header = txt[0].split(',');
const idx = Object.fromEntries(header.map((h, i) => [h, i]));

// naive CSV split is unsafe for quoted commas, but these numeric/owner cols are unquoted
function parseLine(line) {
  // split respecting simple quotes
  const out = []; let cur = ''; let q = false;
  for (const c of line) {
    if (c === '"') q = !q;
    else if (c === ',' && !q) { out.push(cur); cur = ''; }
    else cur += c;
  }
  out.push(cur);
  return out;
}
const mid = s => { const m = /(\d+)-(\d+)/.exec(s); return m ? (+m[1] + +m[2]) / 2 : 0; };

const rows = txt.slice(1).map(l => {
  const c = parseLine(l);
  const pos = +c[idx.positive_ratings] || 0, neg = +c[idx.negative_ratings] || 0;
  const tot = pos + neg;
  return {
    name: c[idx.name], pos, neg, tot,
    ratio: tot ? pos / tot : 0,
    own: mid(c[idx.owners]),
    play: +c[idx.average_playtime] || 0,
    price: +c[idx.price] || 0,
  };
});
const n = rows.length;
console.log('games:', n);

const pad = (s, w) => String(s).slice(0, w).padEnd(w);
function top(key, label, k = 8) {
  console.log(`\n== Top ${k} by ${label} ==`);
  [...rows].sort((a, b) => b[key] - a[key]).slice(0, k).forEach(x =>
    console.log(`  ${pad(x.name, 34)} own~${String(Math.round(x.own)).padStart(10)}  revs=${String(x.tot).padStart(7)}  pos%=${(x.ratio * 100).toFixed(1).padStart(5)}  play=${x.play}`));
}
top('own', 'estimated owners (visibility / reach)');
top('tot', 'number of ratings (engagement volume)');

const q = rows.filter(r => r.tot >= 2000);
console.log(`\n== Top 8 by positive ratio (>=2000 reviews) ==  [${q.length} games qualify]`);
[...q].sort((a, b) => b.ratio - a.ratio).slice(0, 8).forEach(x =>
  console.log(`  ${pad(x.name, 34)} pos%=${(x.ratio * 100).toFixed(1).padStart(5)}  revs=${String(x.tot).padStart(7)}  own~${Math.round(x.own)}`));

const setOwn = new Set([...rows].sort((a, b) => b.own - a.own).slice(0, 50).map(x => x.name));
const setQ = new Set([...q].sort((a, b) => b.ratio - a.ratio).slice(0, 50).map(x => x.name));
const overlap = [...setOwn].filter(x => setQ.has(x)).length;
console.log(`\nOverlap of Top-50 reach vs Top-50 quality: ${overlap} / 50`);

const ownsSorted = rows.map(r => r.own).sort((a, b) => a - b);
const median = ownsSorted[Math.floor(n / 2)];
const totOwn = rows.reduce((s, r) => s + r.own, 0);
const top1 = [...rows].sort((a, b) => b.own - a.own).slice(0, Math.floor(n * 0.01)).reduce((s, r) => s + r.own, 0);
const zero = rows.filter(r => r.tot === 0).length;
console.log('\nReach is highly skewed:');
console.log('  median estimated owners ~', median);
console.log(`  top 1% of games hold ${(top1 / totOwn * 100).toFixed(1)}% of all estimated owners`);
console.log(`  games with zero ratings: ${zero} (${(zero / n * 100).toFixed(1)}%)`);

